source("pre.R")
P <- function(label, expr) { cat("---", label, ": "); r <- tryCatch(expr, error = function(e) cat("ERROR<", class(e)[1], ">:", conditionMessage(e), "\n")); if (!is.null(r)) { if (is.character(r)) cat(r, sep = "\n") else try_(print(r)) }; invisible(r) }
P("expires_in named", { t <- jwt_encode(list(), key, "HS256", expires_in = c(ttl = 60), issued_at = FALSE); cat(payload_of(t), "\n"); jwt_decode(t, key, "HS256") })
P("exp named", { t <- jwt_encode(list(exp = c(t = 1.9e9)), key, "HS256", issued_at = FALSE); jwt_decode(t, key, "HS256") })
P("not_before named", payload_of(jwt_encode(list(), key, "HS256", not_before = c(x = 0), issued_at = FALSE)))
P("exp 1x1 matrix", payload_of(jwt_encode(list(exp = matrix(1.9e9)), key, "HS256", issued_at = FALSE)))
P("exp classed numeric", payload_of(jwt_encode(list(exp = structure(1.9e9, class = "foo")), key, "HS256", issued_at = FALSE)))
P("exp integer64-like Date-time numeric_version", payload_of(jwt_encode(list(exp = 1.9e9, iat = TRUE), key, "HS256")))
P("p2c named", header_of(jwe_encrypt("x", jwk_oct(charToRaw("pw")), "PBES2-HS256+A128KW", header = list(p2c = c(n = 1000)))))
u <- "café \"q\"\n"
for (f in c("compact", "flattened", "general")) P(paste("b64=FALSE nonascii", f), { t <- jws_sign(u, key, "HS256", format = f, b64 = FALSE, detached = f == "compact"); v <- jws_verify(t, key, "HS256", payload = if (f == "compact") u); identical(v$payload, charToRaw(enc2utf8(u))) })
P("latin1 payload", identical(jws_verify(jws_sign(iconv("café", "UTF-8", "latin1"), key, "HS256"), key, "HS256")$payload, charToRaw("café")))
P("latin1 plaintext jwe", { k <- jwk_oct(as.raw(1:16)); identical(jwe_decrypt(jwe_encrypt(iconv("café", "UTF-8", "latin1"), k, "A128KW"), k, "A128KW", "A128CBC-HS256")$plaintext, charToRaw("café")) })
P("latin1 claim + kid + header", { t <- jwt_encode(list(iss = iconv("café", "UTF-8", "latin1")), jwk_oct(as.raw(1:32), kid = iconv("clé", "UTF-8", "latin1")), "HS256", expires_in = 60, header = list(typ = "JWT", x = iconv("é", "UTF-8", "latin1"))); cl <- jwt_decode(t, jwk_set(jwk_oct(as.raw(1:32), kid = "clé")), "HS256", issuer = "café"); c(cl$iss == "café", attr(cl, "header")$x == "é") })
P("latin1 claim name", payload_of(jwt_encode(setNames(list(1), iconv("é", "UTF-8", "latin1")), key, "HS256", issued_at = FALSE)) == "{\"é\":1}")
P("bytes-marked string payload", { x <- "caf\xe9"; Encoding(x) <- "bytes"; jws_sign(x, key, "HS256") })
P("invalid utf8 unmarked payload", { x <- "caf\xe9"; t <- jws_sign(x, key, "HS256"); jws_verify(t, key, "HS256")$payload })
P("embedded NUL raw payload JWT", jwt_decode(jws_sign(as.raw(c(0x7b, 0x7d, 0x00)), key, "HS256"), key, "HS256", required = character()))
P("thumbprint under factor hash", jwk_thumbprint(key, factor("sha256")))
P("jwk_thumbprint uri NA", jwk_thumbprint(key, uri = NA))
